import type { Page } from '@playwright/test';

/**
 * Checkout page object for TechShop.
 *
 * TechShop is hand-written HTML with no build step, so there are no generated
 * class names to select on: every locator here is a data-testid.
 */
export class CheckoutPage {
  constructor(private readonly page: Page) {}

  get form() { return this.page.getByTestId('checkout-form'); }
  get name() { return this.page.getByTestId('input-name'); }
  get email() { return this.page.getByTestId('input-email'); }
  get phone() { return this.page.getByTestId('input-phone'); }
  get phoneError() { return this.page.getByTestId('input-phone-error'); }
  get address() { return this.page.getByTestId('input-address'); }
  get city() { return this.page.getByTestId('input-city'); }
  get zip() { return this.page.getByTestId('input-zip'); }
  get country() { return this.page.getByTestId('input-country'); }
  get placeOrder() { return this.page.getByTestId('place-order-btn'); }
  get orderSuccess() { return this.page.getByTestId('order-success'); }
  get cartCount() { return this.page.getByTestId('cart-count'); }
  get subtotal() { return this.page.getByTestId('subtotal'); }
  get shipping() { return this.page.getByTestId('shipping'); }
  get total() { return this.page.getByTestId('total'); }

  async goto(): Promise<void> {
    await this.page.goto('/checkout.html');
  }

  async fillDetails(details: {
    name: string;
    email: string;
    phone: string;
    address: string;
    city: string;
    zip: string;
    country: string;
  }): Promise<void> {
    await this.name.fill(details.name);
    await this.email.fill(details.email);
    await this.phone.fill(details.phone);
    await this.address.fill(details.address);
    await this.city.fill(details.city);
    await this.zip.fill(details.zip);
    await this.country.fill(details.country);
  }

  async submit(): Promise<void> {
    await this.placeOrder.click();
  }

  /** Reads the money row values as trimmed strings, for cross-page comparison. */
  async totals(): Promise<{ subtotal: string; shipping: string; total: string }> {
    return {
      subtotal: (await this.subtotal.innerText()).trim(),
      shipping: (await this.shipping.innerText()).trim(),
      total: (await this.total.innerText()).trim(),
    };
  }
}

