import { expect, test } from '@playwright/test';
import { CheckoutPage } from '../pages/CheckoutPage';

const DETAILS = {
  name: 'Wilma Fadel',
  email: 'Wilma_Fadel48@yahoo.com',
  phone: '+40 721 555 019',
  address: '4821 Bergstrom Landing',
  city: 'Lake Rebeka',
  zip: '48210',
  country: 'Romania',
};

test.describe('TS-142 — checkout accepts international phone numbers', () => {
  test('places the order when the phone number has a country code', async ({ page }) => {
    const checkout = new CheckoutPage(page);
    await checkout.goto();
    await checkout.fillDetails(DETAILS);
    await checkout.submit();

    await expect(checkout.orderSuccess).toBeVisible();
  });

  test('still accepts a plain 10-digit number', async ({ page }) => {
    const checkout = new CheckoutPage(page);
    await checkout.goto();
    await checkout.fillDetails({ ...DETAILS, phone: '0721555019' });
    await checkout.submit();

    await expect(checkout.orderSuccess).toBeVisible();
  });

  test('rejects a number with fewer than 7 digits without submitting', async ({ page }) => {
    const checkout = new CheckoutPage(page);
    await checkout.goto();
    await checkout.fillDetails({ ...DETAILS, phone: '12345' });
    await checkout.submit();

    await expect(checkout.phoneError).toBeVisible();
    await expect(checkout.orderSuccess).toBeHidden();
  });

  test('empties the cart badge after a successful order', async ({ page }) => {
    const checkout = new CheckoutPage(page);
    await checkout.goto();
    await checkout.fillDetails(DETAILS);
    await checkout.submit();

    await expect(checkout.orderSuccess).toBeVisible();
    await expect(checkout.cartCount).toHaveText('0');
  });

  test('shows the same money rows as the cart page for one basket', async ({ page }) => {
    const checkout = new CheckoutPage(page);

    await page.goto('/cart.html');
    const fromCart = {
      subtotal: (await page.getByTestId('subtotal').innerText()).trim(),
      shipping: (await page.getByTestId('shipping').innerText()).trim(),
      total: (await page.getByTestId('total').innerText()).trim(),
    };

    await checkout.goto();
    expect(await checkout.totals()).toEqual(fromCart);
  });
});
